/**
 * generate-knowledge-base.ts — YAML → TypeScript constant generation
 *
 * Reads spec/kernel/tables/*.yaml and produces typed TS constants
 * in src/shell/renderer/knowledge-base/gen/.
 *
 * @generated — run via `pnpm generate:knowledge-base`
 */

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse as parseYaml } from 'yaml';
import { readKnowledgeAssetData } from './knowledge-json-asset.js';
import { loadKnowledgeAsset } from './knowledge-asset-kernel.js';
import {
  ACTION_TYPE_TO_KIND,
  liftOrthodonticRules,
  type BaseReminderRule,
} from './generate-knowledge-base-reminders.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const TABLES = resolve(ROOT, 'spec/kernel/tables');
const DATA_KNOWLEDGE = resolve(ROOT, 'data/knowledge');
const OUT = resolve(ROOT, 'src/shell/renderer/knowledge-base/gen');
const RUST_OUT = resolve(ROOT, 'src-tauri/src/sqlite/queries');

mkdirSync(OUT, { recursive: true });
mkdirSync(RUST_OUT, { recursive: true });

const HEADER = `// @generated — do not edit manually\n// Generated by scripts/generate-knowledge-base.ts\n\n`;

function readYaml(filename: string): unknown {
  const raw = readFileSync(resolve(TABLES, filename), 'utf-8');
  return parseYaml(raw);
}

function readKnowledgeAsset(assetId: string): unknown {
  return readKnowledgeAssetData(DATA_KNOWLEDGE, assetId);
}

const KNOWLEDGE_ASSET_IDS = [
  'growth-standards',
  'milestone-catalog',
  'sensitive-periods',
  'observation-framework',
  'ability-model',
] as const;

function loadKnowledgeAssetForProjection(assetId: string) {
  return loadKnowledgeAsset({
    dataKnowledgeRoot: DATA_KNOWLEDGE,
    assetId,
    manifestPath: resolve(DATA_KNOWLEDGE, 'assets', assetId, 'asset.json'),
  });
}

function writeGen(filename: string, content: string) {
  writeFileSync(resolve(OUT, filename), HEADER + content, 'utf-8');
  console.log(`  wrote ${filename}`);
}

function rustString(value: string) {
  return JSON.stringify(value);
}

function writeRustGen(filename: string, content: string) {
  writeFileSync(resolve(RUST_OUT, filename), `// @generated - do not edit manually\n// Generated by scripts/generate-knowledge-base.ts\n\n${content}`, 'utf-8');
  console.log(`  wrote ${filename}`);
}

// ── reminder-rules ──────────────────────────────────────────

function generateReminderRules() {
  const data = readYaml('reminder-rules.yaml') as { rules: BaseReminderRule[] };
  const extendedData = readYaml('reminder-rules-extended.yaml') as { rules: BaseReminderRule[] };
  const orthoRules = liftOrthodonticRules(readYaml);
  const merged: BaseReminderRule[] = [...data.rules, ...extendedData.rules, ...orthoRules];

  // Enforce unique ruleIds across the union.
  const seen = new Set<string>();
  for (const rule of merged) {
    if (seen.has(rule.ruleId)) {
      throw new Error(
        `generate-knowledge-base: duplicate ruleId "${rule.ruleId}" detected while unioning reminder-rules.yaml with orthodontic-protocols.yaml`,
      );
    }
    seen.add(rule.ruleId);
  }

  // Enforce PO-TIME-009: orthodontic protocol rules must be push in all modes.
  for (const rule of orthoRules) {
    if (rule.ruleId.startsWith('PO-ORTHO-')) {
      for (const mode of ['relaxed', 'balanced', 'advanced'] as const) {
        if (rule.nurtureMode[mode] !== 'push') {
          throw new Error(
            `generate-knowledge-base: orthodontic rule "${rule.ruleId}" must be push in all nurture modes (PO-TIME-009); got ${mode}=${rule.nurtureMode[mode]}`,
          );
        }
      }
    }
  }

  // PO-REMI-002: enforce actionType ↔ kind mapping for every merged rule.
  for (const rule of merged) {
    const expected = ACTION_TYPE_TO_KIND[rule.actionType];
    if (!expected) {
      throw new Error(
        `generate-knowledge-base: rule "${rule.ruleId}" has unknown actionType '${rule.actionType}'`,
      );
    }
    if (rule.kind !== expected) {
      throw new Error(
        `generate-knowledge-base: rule "${rule.ruleId}" kind '${rule.kind}' does not match PO-REMI-002 mapping for actionType '${rule.actionType}' (expected '${expected}')`,
      );
    }
  }

  const domains = [...new Set(merged.map((r) => r.domain))].sort();
  const categories = [...new Set(merged.map((r) => r.category))].sort();
  const priorities = [...new Set(merged.map((r) => r.priority))].sort();
  const actionTypes = [...new Set(merged.map((r) => r.actionType))].sort();
  const kinds = [...new Set(merged.map((r) => r.kind))].sort();

  const ts = `
export type ReminderDomain = ${domains.map((d) => `'${d}'`).join(' | ')};
export type ReminderCategory = ${categories.map((c) => `'${c}'`).join(' | ')};
export type ReminderPriority = ${priorities.map((p) => `'${p}'`).join(' | ')};
export type ReminderVisibility = 'push' | 'silent' | 'hidden';
export type ActionType = ${actionTypes.map((a) => `'${a}'`).join(' | ')};
export type ReminderKind = ${kinds.map((k) => `'${k}'`).join(' | ')};

export interface ReminderExplainSource {
  citation: string;
  url?: string;
}

export interface ReminderExplain {
  whyNow: string;
  howTo: readonly string[];
  doneWhen: string;
  ifNotNow?: string;
  pitfalls?: readonly string[];
  sources: readonly ReminderExplainSource[];
}

export interface ReminderRule {
  ruleId: string;
  domain: ReminderDomain;
  category: ReminderCategory;
  kind: ReminderKind;
  title: string;
  description: string;
  triggerAge: { startMonths: number; endMonths: number };
  triggerCondition?: { dataField: string; operator: string; value: unknown };
  priority: ReminderPriority;
  nurtureMode: { relaxed: ReminderVisibility; balanced: ReminderVisibility; advanced: ReminderVisibility };
  actionType: ActionType;
  repeatRule?: { intervalMonths: number; maxRepeats: number };
  explain?: ReminderExplain;
  expiryMonths?: number;
  tags?: readonly string[];
}

export const REMINDER_RULES: readonly ReminderRule[] = ${JSON.stringify(merged, null, 2)};

export const REMINDER_DOMAINS = ${JSON.stringify(domains)} ;
export const REMINDER_KINDS = ${JSON.stringify(kinds)} ;
`;

  writeGen('reminder-rules.gen.ts', ts);
}

